"""Minimal PyTorch dataset loader for converted ACT episode packages."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import numpy as np
import torch
from torch.utils.data import Dataset


class LerobotActEpisodeDataset(Dataset):
    """Load dataset generated by `convert_to_lerobot_act.py`."""

    def __init__(self, dataset_dir: str | Path, split: str = "train") -> None:
        self.dataset_dir = Path(dataset_dir).expanduser().resolve()
        if split not in {"train", "val", "all"}:
            raise ValueError("split must be one of: train, val, all")
        self.split = split

        metadata_path = self.dataset_dir / "metadata.json"
        if not metadata_path.exists():
            raise FileNotFoundError(f"metadata.json not found: {metadata_path}")
        with metadata_path.open("r", encoding="utf-8") as metadata_file:
            self.metadata = json.load(metadata_file)

        if split == "all":
            episode_ids = [episode["episode_id"] for episode in self.metadata["episodes"]]
        else:
            split_path = self.dataset_dir / "splits" / f"{split}_episode_ids.npy"
            if not split_path.exists():
                raise FileNotFoundError(f"Split file not found: {split_path}")
            episode_ids = np.load(split_path, allow_pickle=False).astype(str).tolist()

        self.episode_files = [self.dataset_dir / "episodes" / f"{episode_id}.npz" for episode_id in episode_ids]
        for episode_file in self.episode_files:
            if not episode_file.exists():
                raise FileNotFoundError(f"Episode file not found: {episode_file}")

        self.sample_index: list[tuple[int, int]] = []
        self.episode_payloads: list[dict[str, np.ndarray]] = []
        for episode_position, episode_file in enumerate(self.episode_files):
            payload = dict(np.load(episode_file, allow_pickle=False))
            self.episode_payloads.append(payload)
            row_count = int(payload["observation_state"].shape[0])
            for row_index in range(row_count):
                self.sample_index.append((episode_position, row_index))

    def __len__(self) -> int:
        return len(self.sample_index)

    def __getitem__(self, index: int) -> dict[str, Any]:
        episode_position, row_index = self.sample_index[index]
        payload = self.episode_payloads[episode_position]

        observation_state = torch.from_numpy(payload["observation_state"][row_index]).float()
        action_chunk = torch.from_numpy(payload["action_chunk"][row_index]).float()
        action_valid_mask = torch.from_numpy(payload["action_valid_mask"][row_index]).bool()
        latency_ms = torch.tensor(float(payload["latency_ms"][row_index]), dtype=torch.float32)
        sample_weight = torch.tensor(float(payload["sample_weight"][row_index]), dtype=torch.float32)
        anchor_mask = torch.tensor(int(payload["anchor_mask"][row_index]), dtype=torch.int64)
        timestamp_s = torch.tensor(float(payload["timestamp_s"][row_index]), dtype=torch.float64)

        sample: dict[str, Any] = {
            "observation_state": observation_state,
            "action_chunk": action_chunk,
            "action_valid_mask": action_valid_mask,
            "latency_ms": latency_ms,
            "sample_weight": sample_weight,
            "anchor_mask": anchor_mask,
            "timestamp_s": timestamp_s,
        }
        if "observation_image_reference" in payload:
            sample["observation_image_reference"] = str(payload["observation_image_reference"][row_index])
        return sample
